    // 像素比上限：触屏设备 1.5（高 DPR 手机像素压力最大，降级显著提帧率），桌面 2
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    // 低端设备降级（#3）：核数 ≤4 → 关软阴影/降 DPR，缓解低端机掉帧
    const lowEnd = (navigator.hardwareConcurrency || 8) <= 4;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, lowEnd ? 1.25 : (isTouch ? 1.5 : 2)));
    this.renderer.shadowMap.enabled = !lowEnd;
    this.renderer.shadowMap.type = lowEnd ? THREE.PCFShadowMap : THREE.PCFSoftShadowMap;
    this.renderer.shadowMap.mapSize.set(1024, 1024);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    // toneMapping（#1）：ACESFilmic 收敛高光，避免环境光强 >1 时过曝
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    gameRoot.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(CONFIG.fov, window.innerWidth / window.innerHeight, 0.05, CONFIG.renderDistance);
    this.scene.add(this.camera);

    // 环境贴图：程序化室内光照（PMREM），让金属枪械/装甲有真实反射，否则金属像灰塑料
    // 环境贴图：程序化室内光照（PMREM），让金属枪械/装甲有真实反射
    // 真机部分 WebGL 实现可能不支持 PMREM，失败仅降级为无环境反射（不影响启动）
    try { this.scene.environment = this._buildEnvironment(); }
    catch (e) { console.error('[cs15] env failed', e); }

    // 地图
    this.gameMap = new GameMap(this.scene);

    // 玩家
    this.player = new Player(this.camera, this.gameMap, this.hud);


